@import "@fontsource-variable/inter";
@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/newsreader/opsz-italic.css";
@import "@fontsource-variable/nunito";

/* Light (faithful): white pages, near-black serif headlines, slate reading text, a vivid
   tangerine (#ff5924) for buttons and the search band, blush (#fff1f1) and warm-grey bands,
   pastel cards. The five chart colours are the outlined tag colours (apricot, orchid, sky,
   coral, sunflower); highlight is the leaf green of the "Log in" dot and the sage cards. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.16 0.006 265);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.16 0.006 265);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.16 0.006 265);
  --primary: oklch(0.681 0.211 37);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.958 0.01 85);
  --secondary-foreground: oklch(0.16 0.006 265);
  --muted: oklch(0.936 0.012 260);
  --muted-foreground: oklch(0.444 0.031 261);
  --accent: oklch(0.969 0.015 17);
  --accent-foreground: oklch(0.16 0.006 265);
  --destructive: oklch(0.6 0.21 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.913 0 90);
  --input: oklch(0.913 0 90);
  --ring: oklch(0.681 0.211 37);
  --highlight: oklch(0.706 0.159 138);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.738 0.145 4);
  --chart-1: oklch(0.732 0.133 53);
  --chart-2: oklch(0.743 0.127 344);
  --chart-3: oklch(0.839 0.082 240);
  --chart-4: oklch(0.691 0.15 25);
  --chart-5: oklch(0.872 0.171 91);
  --sidebar: oklch(0.985 0.003 265);
  --sidebar-foreground: oklch(0.16 0.006 265);
  --sidebar-primary: oklch(0.681 0.211 37);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.969 0.015 17);
  --sidebar-accent-foreground: oklch(0.16 0.006 265);
  --sidebar-border: oklch(0.913 0 90);
  --sidebar-ring: oklch(0.681 0.211 37);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Newsreader Variable", "Iowan Old Style", Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* not a token: the rounded face of pills, buttons and small capitals in mymind blocks */
  --mymind-round: "Nunito Variable", "Nunito", ui-rounded, ui-sans-serif, system-ui, sans-serif;
  --radius: 1rem;
  --page-width: 81.75rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark (sibling): warm black with a faint rose cast, off-white serif, the same tangerine a
   touch lighter, pastel tones turned into dim tints of themselves. */
.dark {
  --background: oklch(0.17 0.008 20);
  --foreground: oklch(0.96 0.006 60);
  --card: oklch(0.215 0.009 20);
  --card-foreground: oklch(0.96 0.006 60);
  --popover: oklch(0.235 0.01 20);
  --popover-foreground: oklch(0.96 0.006 60);
  --primary: oklch(0.7 0.2 38);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.25 0.012 70);
  --secondary-foreground: oklch(0.96 0.006 60);
  --muted: oklch(0.255 0.014 260);
  --muted-foreground: oklch(0.74 0.025 260);
  --accent: oklch(0.235 0.022 17);
  --accent-foreground: oklch(0.96 0.006 60);
  --destructive: oklch(0.66 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 11%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.7 0.2 38);
  --highlight: oklch(0.74 0.15 138);
  --highlight-foreground: oklch(0.17 0.008 20);
  --glow: oklch(0.62 0.15 4);
  --chart-1: oklch(0.76 0.13 53);
  --chart-2: oklch(0.76 0.12 344);
  --chart-3: oklch(0.8 0.09 240);
  --chart-4: oklch(0.71 0.15 25);
  --chart-5: oklch(0.86 0.16 91);
  --sidebar: oklch(0.2 0.008 20);
  --sidebar-foreground: oklch(0.96 0.006 60);
  --sidebar-primary: oklch(0.7 0.2 38);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.235 0.022 17);
  --sidebar-accent-foreground: oklch(0.96 0.006 60);
  --sidebar-border: oklch(1 0 0 / 11%);
  --sidebar-ring: oklch(0.7 0.2 38);
}
